#!/bin/sh
# Route A on the unit (research/mt8163-isp-pass2.md, "Stage 5"): one packed RAW10 1600x1200 frame
# through ISP pass 2 (UNP, CFA, G2C, C42, the resampler CRSP, the MDP crop) straight into the MDP
# (CAMIN -> RSZ1 -> WROT), which writes I420 with its 4:2:0 average, three tiles, one pass-2 start a
# tile. Run with the capture stopped (touch /run/techo5/hold; kill $(pidof techo5)), debugfs mounted
# and both harness modules loaded (insmod isp2test.ko; insmod mdptest.ko):
#
#   tools/link.sh in.raw tdr.bin outdir      -> outdir/out.i420, isp.log, mdp.log
#
# tdr.bin is DpFramework's table for the path, 18 words (dpcap isp 0 0 I420 0 96=0, RSP on): per
# tile its control word, IMGI offset and size, the unpacker's bits and the MDP crop. The register
# values are the camera driver's run_pass2_link and link_* (patches/mt8163-cronos-camera.c).
set -u
RAW=$1 TDR=$2 OUT=$3
I=/sys/kernel/debug/isp2test M=/sys/kernel/debug/mdptest
mkdir -p $OUT
cat "$RAW" > $I/imgi
dd if="$TDR" of=$I/tdr conv=notrunc 2>/dev/null
echo clear > $I/ctl; echo clear > $M/ctl
echo "fill i420 0x55" > $M/ctl
icmd() { echo "$1" > $I/ctl || echo "isp failed: $1"; }
mcmd() { echo "$1" > $M/ctl || echo "mdp failed: $1"; }
icmd on; icmd reset; mcmd on; mcmd rst
for c in "w 0x000 0" "w 0x150 0x1ffff" "w 0x410 0 0" "w 0x020 0x5fbbf41f" "w 0x26c @aux" "w 0x300 @aux" "w 0x36c @aux" "w 0x388 @aux" "w 0x0a8 0 0 0 0 0 0" "w 0x010 0x00011103" "w 0x004 0x00300000" "w 0x008 0x00800003" "w 0x00c 0x00000080" "w 0x018 0x40" "w 0x01c 0x00100003" "w 0x074 0 0" "w 0x230 @imgi 0 1999 1199 2000" "w 0x320 @img2o 0 3199 1199 3200" "w 0xa04 0x0000003a" "w 0xa0c 0x00000100" "w 0xa14 0x000007d6" "w 0xa1c 0" "w 0x054 0x98100003"; do icmd "$c"; done
mcmd "w 0x14003000 0x10000 0x10000"; mcmd "w 0x14003000 0 0x10000"; mcmd "w 0x14003000 1 1"; mcmd "w 0x14005010 1 1"; mcmd "p 0x14005014 1 1 10"; mcmd "w 0x14005010 0 1"; mcmd "p 0x14005014 0 1 10"; mcmd "w 0x14003000 0 1"
mcmd "w 0x14005f00 @i420"; mcmd "w 0x14005f04 @i420+1920000"; mcmd "w 0x14005f08 @i420+2400000"
for c in "0x14005000 0x00005008 0xf131510f" "0x14005074 0x0006005c 0x00ffffff" "0x14005030 1600 0xffff" "0x1400503c 800 0xffff" "0x1400506c 800 0xffff" "0x14005084 0 0xf3" "0x14005054 0xff000000 0xff000000" "0x14005070 0x80000000 0x80000000" "0x1400507c 0x00900000 0x00900000"; do mcmd "w $c"; done
icmd "us 1"
# tile 0: x 0, 762 wide
for c in "0x140150ec 0x24 0x07ffffff" "0x140150f0 0 7" "0x1400001c 2 0xffffffff" "0x14000028 2 0xffffffff" "0x14000048 0 0xffffffff" "0x14000054 1 0xffffffff"; do mcmd "w $c"; done
for c in "0x1400502c 0 0x0fffffff" "0x14005038 0 0x0fffffff" "0x14005068 0 0x0fffffff" "0x14005078 0x4b002fa 0x1fff1fff" "0x14005024 0x4b002fa 0x1fff1fff" "0x14005020 0 0x1fff1fff" "0x14005008 0x2fa1430 0x1fff7f77" "0x1400507c 1 1" "0x1400300c 0x84b002fa 0xdfff1fff" "0x1400301c 0 0x1fff" "0x14003020 0 0x1fffff" "0x14003024 0 0x1fff" "0x14003028 0 0x1fffff" "0x1400302c 0 0x1fff" "0x14003030 0 0x1fffff" "0x14003034 0 0x1fff" "0x14003038 0 0x1fffff" "0x14003010 0x84b002fa 0x9fff1fff"; do mcmd "w $c"; done
mcmd "w 0x140150e0 1 1"; mcmd "p 0x140150e0 0 1 10"; mcmd "w 0x140150ec 0 0x07ffffff"
icmd "w 0x050 0x0012d32d"; icmd "w 0x110 0x02f98000 0x04af0000"; icmd "w 0x204 @tdr+0 0 23"
icmd "run 0x000 1 500 0x4000"
mcmd "w 0x14005018 0x1400 0xffffffff"; mcmd "p 0x140050d0 0 0xffff 20"
for c in "0x1400507c 0 1" "0x1400001c 0" "0x14000028 0" "0x14000048 0" "0x14000054 0"; do mcmd "w $c"; done
# tile 1: x 762, 756 wide
for c in "0x140150ec 0x24 0x07ffffff" "0x140150f0 0 7" "0x1400001c 2 0xffffffff" "0x14000028 2 0xffffffff" "0x14000048 0 0xffffffff" "0x14000054 1 0xffffffff"; do mcmd "w $c"; done
for c in "0x1400502c 762 0x0fffffff" "0x14005038 381 0x0fffffff" "0x14005068 381 0x0fffffff" "0x14005078 0x4b002f4 0x1fff1fff" "0x14005024 0x4b002f4 0x1fff1fff" "0x14005020 0 0x1fff1fff" "0x14005008 0x2f41430 0x1fff7f77" "0x1400507c 1 1" "0x1400300c 0xc4b002f4 0xdfff1fff" "0x1400301c 0 0x1fff" "0x14003020 0 0x1fffff" "0x14003024 0 0x1fff" "0x14003028 0 0x1fffff" "0x1400302c 0 0x1fff" "0x14003030 0 0x1fffff" "0x14003034 0 0x1fff" "0x14003038 0 0x1fffff" "0x14003010 0x84b002f4 0x9fff1fff"; do mcmd "w $c"; done
mcmd "w 0x140150e0 1 1"; mcmd "p 0x140150e0 0 1 10"; mcmd "w 0x140150ec 0 0x07ffffff"
icmd "w 0x050 0x0012c32c"; icmd "w 0x110 0x02f38000 0x04af0000"; icmd "w 0x204 @tdr+24 0 23"
icmd "run 0x000 1 500 0x4000"
mcmd "w 0x14005018 0x1400 0xffffffff"; mcmd "p 0x140050d0 0 0xffff 20"
for c in "0x1400507c 0 1" "0x1400001c 0" "0x14000028 0" "0x14000048 0" "0x14000054 0"; do mcmd "w $c"; done
# tile 2: x 1518, 82 wide
for c in "0x140150ec 0x24 0x07ffffff" "0x140150f0 0 7" "0x1400001c 2 0xffffffff" "0x14000028 2 0xffffffff" "0x14000048 0 0xffffffff" "0x14000054 1 0xffffffff"; do mcmd "w $c"; done
for c in "0x1400502c 1518 0x0fffffff" "0x14005038 759 0x0fffffff" "0x14005068 759 0x0fffffff" "0x14005078 0x4b00052 0x1fff1fff" "0x14005024 0x4b00052 0x1fff1fff" "0x14005020 0 0x1fff1fff" "0x14005008 0x524030 0x1fff7f77" "0x1400507c 1 1" "0x1400300c 0xc4b00052 0xdfff1fff" "0x1400301c 0 0x1fff" "0x14003020 0 0x1fffff" "0x14003024 0 0x1fff" "0x14003028 0 0x1fffff" "0x1400302c 0 0x1fff" "0x14003030 0 0x1fffff" "0x14003034 0 0x1fff" "0x14003038 0 0x1fffff" "0x14003010 0x4b00052 0x9fff1fff"; do mcmd "w $c"; done
mcmd "w 0x140150e0 1 1"; mcmd "p 0x140150e0 0 1 10"; mcmd "w 0x140150ec 0 0x07ffffff"
icmd "w 0x050 0x0012e32e"; icmd "w 0x110 0x00518000 0x04af0000"; icmd "w 0x204 @tdr+48 0 23"
icmd "run 0x000 1 500 0x4000"
mcmd "w 0x14005018 0x1400 0xffffffff"; mcmd "p 0x140050d0 0 0xffff 20"
for c in "0x1400507c 0 1" "0x1400001c 0" "0x14000028 0" "0x14000048 0" "0x14000054 0"; do mcmd "w $c"; done
mcmd rst; icmd reset
cat $I/log > $OUT/isp.log; cat $M/ctl > $OUT/mdp.log
head -c 2880000 $M/i420 > $OUT/out.i420
mcmd off; icmd off
